// 苍玄界：全局悬浮状态栏脚本
// 外部导入版。脚本运行在 Tavern Helper 脚本上下文，状态栏界面运行在同源 iframe 中。
// 关键点：iframe 内部不得直接假设存在全局 Mvu；所有 MVU/API 访问都从父级 TH 脚本上下文桥接。
$(() => {
  const BUILD_ID = 'cangxuan-v1.0.24';
  const INSTANCE_ID = `${BUILD_ID}-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const ROOT_ID = 'cx-floating-status-root';
  const STYLE_ID = 'cx-floating-status-style';
  const PANEL_ID = 'cx-floating-status-panel';
  const FRAME_ID = 'cx-floating-status-frame';
  const TOGGLE_ID = 'cx-floating-status-toggle';
  const POSITION_KEY = 'cx-floating-status-position';
  const FRAME_BUILD_ATTR = 'cxStatusFrameBuild';
  const STATUS_HTML_BASE64 = "";

  function decodeBase64Utf8(base64) {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
    return new TextDecoder('utf-8').decode(bytes);
  }

  function getOuterGlobal(name) {
    try {
      if (globalThis[name] !== undefined) return globalThis[name];
    } catch (_) {}
    try {
      if (window.parent && window.parent !== window && window.parent[name] !== undefined) return window.parent[name];
    } catch (_) {}
    return undefined;
  }

  function getHostWindow() {
    try {
      if (window.parent && window.parent !== window && window.parent.document) return window.parent;
    } catch (_) {}
    return window;
  }

  function getHostDocument() {
    return getHostWindow().document;
  }

  const PROMPT_INPUT_SELECTORS = [
    '#send_textarea',
    'textarea#send_textarea',
    'textarea[name="send_textarea"]',
    'textarea.mdHotkeys[placeholder*="发送"]',
    'textarea[placeholder*="想发送"]',
    'textarea[placeholder*="/?"]',
    '#send_form textarea',
    '#send_textarea textarea',
    '.send_textarea',
    '[contenteditable="true"]#send_textarea',
    '[contenteditable="true"][data-testid="send_textarea"]',
    '[contenteditable="true"][role="textbox"][aria-label*="发送"]',
    '[contenteditable="true"][role="textbox"][aria-label*="message"]',
  ];

  function isVisiblePromptInput(el) {
    if (!el) return false;
    try {
      const rect = el.getBoundingClientRect();
      const style = getHostWindow().getComputedStyle?.(el);
      if (style && (style.display === 'none' || style.visibility === 'hidden')) return false;
      return Boolean(el.offsetWidth || el.offsetHeight || el.getClientRects().length)
        && rect.bottom > 0
        && rect.right > 0
        && rect.top < (getHostWindow().innerHeight || 0)
        && rect.left < (getHostWindow().innerWidth || 0);
    } catch (_) {
      return true;
    }
  }

  function findSendTextarea() {
    const hostDoc = getHostDocument();
    for (const selector of PROMPT_INPUT_SELECTORS) {
      try {
        const matches = [...hostDoc.querySelectorAll(selector)];
        const visible = matches.find(isVisiblePromptInput);
        if (visible) return visible;
        if (matches[0]) return matches[0];
      } catch (_) {}
    }
    return null;
  }

  function setElementInputText(el, text) {
    if (!el) return false;
    const hostWin = getHostWindow();
    if ('value' in el) {
      const proto = el instanceof hostWin.HTMLTextAreaElement
        ? hostWin.HTMLTextAreaElement.prototype
        : (el instanceof hostWin.HTMLInputElement ? hostWin.HTMLInputElement.prototype : Object.getPrototypeOf(el));
      const descriptor = Object.getOwnPropertyDescriptor(proto, 'value')
        || Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value');
      if (descriptor?.set) descriptor.set.call(el, text);
      else el.value = text;
      try { el.setSelectionRange(text.length, text.length); } catch (_) {}
      return true;
    }
    if (el.isContentEditable || el.getAttribute?.('contenteditable') === 'true') {
      el.textContent = text;
      return true;
    }
    return false;
  }

  function dispatchInputEvents(el, text) {
    if (!setElementInputText(el, text)) return false;
    const hostWin = getHostWindow();
    const EventCtor = hostWin.Event || Event;
    try {
      const InputEventCtor = hostWin.InputEvent || InputEvent;
      el.dispatchEvent(new InputEventCtor('beforeinput', { bubbles: true, inputType: 'insertText', data: text }));
      el.dispatchEvent(new InputEventCtor('input', { bubbles: true, inputType: 'insertText', data: text }));
    } catch (_) {
      el.dispatchEvent(new EventCtor('input', { bubbles: true }));
    }
    el.dispatchEvent(new EventCtor('change', { bubbles: true }));
    try {
      const jq = getOuterGlobal('$');
      if (jq) jq(el).val?.(text).trigger('input').trigger('change');
    } catch (_) {}
    try {
      el.focus({ preventScroll: false });
    } catch (_) {
      try { el.focus(); } catch (__) {}
    }
    return true;
  }

  function escapeSlashText(text) {
    return String(text)
      .replace(/\\/g, '\\\\')
      .replace(/\r?\n/g, '\\n');
  }

  async function setTavernInputDraft(text) {
    const draft = String(text || '').trim();
    if (!draft) return false;

    const input = findSendTextarea();
    if (dispatchInputEvents(input, draft)) return true;

    const triggerSlashFn = getOuterGlobal('triggerSlash');
    if (typeof triggerSlashFn === 'function') {
      await triggerSlashFn(`/setinput ${escapeSlashText(draft)}`);
      return true;
    }
    return false;
  }

  function buildInteractionDraft(type, target = '', content = '') {
    const safeType = String(type || '交互');
    const safeTarget = String(target || '').trim();
    const safeContent = String(content || '').trim();
    switch (safeType) {
      case '飞剑传书':
        return [
          `我通过状态栏确认：回复飞剑传书给【${safeTarget || '未知收信人'}】。`,
          `回信内容：${safeContent || '（空）'}`,
          '请在本轮剧情中处理这次传书；若对方未正式结识、不在道友录或不具备传书资格，请写明失败原因，不要更新最新传讯。若处理成功，请输出完整<飞剑回信>标签块，并在<UpdateVariable>中更新相关变量。',
        ].join('\n');
      case '拍卖行购买':
        return [
          `我想购买随身拍卖行里的【${safeTarget || '未知拍品'}】。`,
          '请先确认该拍品仍存在且我的灵石足够；成功则在<UpdateVariable>中扣除灵石、移除拍品、加入背包，并输出完整<拍卖购入>标签块。若失败，请只说明失败原因，不要扣费。',
        ].join('\n');
      case '悬赏接取':
        return [
          `我想接取委托板上的【${safeTarget || '未知委托'}】。`,
          '请直接接取该委托，在<UpdateVariable>中移除该委托，并输出完整<赏令接取>标签块。',
        ].join('\n');
      case '盲盒开启':
        return [
          `我想开启【${safeTarget || '万界盲盒'}】${safeContent ? `（${safeContent}）` : ''}。`,
          '请先确认灵石足够；成功则在<UpdateVariable>中扣费并发放符合当前境界与剧情的物品，同时输出完整<盲盒开启>标签块。若失败，请只说明失败原因，不要扣费。',
        ].join('\n');
      case '背包丢弃':
        return [
          `我想丢弃背包中的【${safeTarget || '未知物品'}】。`,
          '请先确认物品存在；成功则在<UpdateVariable>中只用delta扣除对应数量，数量归零交给底层引擎清理。若失败，请只说明失败原因，不要修改背包。',
        ].join('\n');
      default:
        return [
          `我通过状态栏选择了一次交互：${safeType}${safeTarget ? `【${safeTarget}】` : ''}。`,
          safeContent ? `补充内容：${safeContent}` : '',
          '请根据当前剧情与变量规则处理；若条件不满足，请说明原因，不要强行改动变量。',
        ].filter(Boolean).join('\n');
    }
  }

  async function writeStatusInteractionToInput(type, target = '', content = '') {
    try {
      const draft = type === '__cx_raw_draft__' ? String(target || '') : buildInteractionDraft(type, target, content);
      const ok = await setTavernInputDraft(draft);
      const toast = getOuterGlobal('toastr');
      if (ok) {
        if (toast && typeof toast.success === 'function') toast.success('已写入发送栏，请确认后手动发送。');
        return true;
      }
      if (toast && typeof toast.warning === 'function') toast.warning('没有找到发送栏，请手动复制状态栏操作内容。');
      alert('没有找到发送栏，请手动复制状态栏操作内容。');
      return false;
    } catch (error) {
      console.warn('[苍玄界状态栏] 写入发送栏失败', error);
      alert('写入发送栏失败，请稍后重试。');
      return false;
    }
  }

  function installInputDraftBridge(win) {
    try {
      win.writeStatusInteraction = writeStatusInteractionToInput;
    } catch (_) {}
    try {
      if (win.__CX_TH__) win.__CX_TH__.writeStatusInteraction = writeStatusInteractionToInput;
    } catch (_) {}
  }

  function getMvuObj() {
    return getOuterGlobal('Mvu');
  }

  async function waitForMvuObj() {
    const waitGlobal = getOuterGlobal('waitGlobalInitialized');
    if (typeof waitGlobal === 'function') {
      try { await waitGlobal('Mvu'); } catch (error) { console.warn('[苍玄界状态栏] 等待 MVU 初始化失败', error); }
    }
    const start = Date.now();
    while (!getMvuObj() && Date.now() - start < 15000) {
      await new Promise(resolve => setTimeout(resolve, 120));
    }
    return getMvuObj();
  }

  function ensureStyle() {
    const hostDoc = getHostDocument();
    if (hostDoc.getElementById(STYLE_ID)) return;
    const style = hostDoc.createElement('style');
    style.id = STYLE_ID;
    style.textContent = `
      #${ROOT_ID} {
        position: fixed;
        right: 18px;
        bottom: 18px;
        width: 34px;
        height: 34px;
        z-index: 99999;
        pointer-events: none;
        font-family: "Microsoft YaHei", "PingFang SC", sans-serif;
      }
      #${TOGGLE_ID} {
        pointer-events: auto;
        width: 34px;
        height: 34px;
        border-radius: 50%;
        border: 1px solid rgba(233, 213, 255, 0.72);
        background: radial-gradient(circle at 35% 25%, rgba(233, 213, 255, 0.28), rgba(15, 23, 42, 0.96) 62%);
        color: #f8fafc;
        box-shadow: 0 8px 22px rgba(0, 0, 0, 0.42), 0 0 14px rgba(167, 139, 250, 0.32);
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
        user-select: none;
        touch-action: none;
      }
      #${TOGGLE_ID}:hover {
        transform: translateY(-2px);
        border-color: rgba(233, 213, 255, 0.95);
        box-shadow: 0 12px 30px rgba(0, 0, 0, 0.52), 0 0 20px rgba(167, 139, 250, 0.46);
      }
      #${TOGGLE_ID} .cx-floating-status-glyph {
        font-size: 17px;
        font-weight: 900;
        line-height: 1;
        letter-spacing: 0;
      }
      #${PANEL_ID} {
        pointer-events: auto;
        position: absolute;
        right: 0;
        bottom: 44px;
        width: min(430px, calc(100vw - 28px));
        height: min(720px, calc(100vh - 110px));
        border-radius: 18px;
        overflow: hidden;
        background: rgba(3, 7, 18, 0.7);
        border: 1px solid rgba(167, 139, 250, 0.28);
        box-shadow: 0 22px 60px rgba(0, 0, 0, 0.58);
        opacity: 0;
        visibility: hidden;
        transform: translateY(10px) scale(0.985);
        transform-origin: right bottom;
        transition: opacity 180ms ease, transform 180ms ease, visibility 180ms ease;
      }
      #${ROOT_ID}.cx-open-down #${PANEL_ID} {
        top: 44px;
        bottom: auto;
        transform-origin: right top;
      }
      #${ROOT_ID}.cx-align-left #${PANEL_ID} {
        left: 0;
        right: auto;
        transform-origin: left bottom;
      }
      #${ROOT_ID}.cx-align-left.cx-open-down #${PANEL_ID} {
        transform-origin: left top;
      }
      #${ROOT_ID}.is-open #${PANEL_ID} {
        opacity: 1;
        visibility: visible;
        transform: translateY(0) scale(1);
      }
      #${FRAME_ID} {
        width: 100%;
        height: 100%;
        border: 0;
        display: block;
        background: transparent;
      }
      @media (max-width: 640px) {
        #${ROOT_ID} {
          right: 12px;
          bottom: 12px;
          width: 38px;
          height: 38px;
        }
        #${TOGGLE_ID} {
          width: 38px;
          height: 38px;
        }
        #${TOGGLE_ID} .cx-floating-status-glyph {
          font-size: 17px;
        }
        #${PANEL_ID} {
          right: 0;
          bottom: 50px;
          width: calc(100vw - 24px);
          height: min(76vh, 680px);
          border-radius: 14px;
        }
        #${ROOT_ID}.cx-open-down #${PANEL_ID} {
          top: 50px;
          bottom: auto;
        }
      }
    `;
    hostDoc.head.appendChild(style);
  }

  function clampNumber(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function clampPosition(value, viewportSize, elementSize) {
    const margin = 8;
    const max = viewportSize - elementSize - margin;
    if (!Number.isFinite(value)) return margin;
    if (!Number.isFinite(max) || max <= margin) return margin;
    return Math.round(clampNumber(value, margin, max));
  }

  function getViewportSize() {
    const hostWin = getHostWindow();
    const hostDoc = getHostDocument();
    return {
      width: hostWin.innerWidth || hostDoc.documentElement.clientWidth || 1024,
      height: hostWin.innerHeight || hostDoc.documentElement.clientHeight || 768,
    };
  }

  function readSavedPosition() {
    try {
      const parsed = JSON.parse(getHostWindow().localStorage.getItem(POSITION_KEY) || 'null');
      if (parsed && Number.isFinite(parsed.left) && Number.isFinite(parsed.top)) return parsed;
    } catch (_) {}
    return null;
  }

  function savePosition(left, top) {
    try {
      getHostWindow().localStorage.setItem(POSITION_KEY, JSON.stringify({ left, top }));
    } catch (_) {}
  }

  function positionRoot(root, left, top, shouldSave = false) {
    const rect = root.getBoundingClientRect();
    const { width, height } = getViewportSize();
    const rootWidth = rect.width || 34;
    const rootHeight = rect.height || 34;
    const nextLeft = clampPosition(left, width, rootWidth);
    const nextTop = clampPosition(top, height, rootHeight);
    root.style.left = `${nextLeft}px`;
    root.style.top = `${nextTop}px`;
    root.style.right = 'auto';
    root.style.bottom = 'auto';
    root.classList.toggle('cx-align-left', nextLeft < width / 2);
    root.classList.toggle('cx-open-down', nextTop < height / 2);
    if (shouldSave) savePosition(nextLeft, nextTop);
  }

  function applyInitialPosition(root) {
    const saved = readSavedPosition();
    const { width, height } = getViewportSize();
    const rect = root.getBoundingClientRect();
    const rootWidth = rect.width || 34;
    const rootHeight = rect.height || 34;
    const left = saved ? saved.left : width - rootWidth - 18;
    const top = saved ? saved.top : height - rootHeight - 18;
    positionRoot(root, left, top, false);
  }

  function installDrag(root, handle) {
    if (handle.dataset.cxDragInstalled === INSTANCE_ID) return;
    handle.dataset.cxDragInstalled = INSTANCE_ID;
    let dragState = null;
    handle.addEventListener('pointerdown', ev => {
      if (ev.button !== undefined && ev.button !== 0) return;
      const rect = root.getBoundingClientRect();
      dragState = {
        pointerId: ev.pointerId,
        startX: ev.clientX,
        startY: ev.clientY,
        left: rect.left,
        top: rect.top,
        moved: false,
      };
      try { handle.setPointerCapture(ev.pointerId); } catch (_) {}
    });
    handle.addEventListener('pointermove', ev => {
      if (!dragState || dragState.pointerId !== ev.pointerId) return;
      const dx = ev.clientX - dragState.startX;
      const dy = ev.clientY - dragState.startY;
      if (Math.abs(dx) + Math.abs(dy) > 3) dragState.moved = true;
      if (dragState.moved) {
        ev.preventDefault();
        positionRoot(root, dragState.left + dx, dragState.top + dy, true);
      }
    });
    const endDrag = ev => {
      if (!dragState || dragState.pointerId !== ev.pointerId) return;
      if (dragState.moved) {
        root.dataset.cxDragged = '1';
        setTimeout(() => { delete root.dataset.cxDragged; }, 0);
      }
      try { handle.releasePointerCapture(ev.pointerId); } catch (_) {}
      dragState = null;
    };
    handle.addEventListener('pointerup', endDrag);
    handle.addEventListener('pointercancel', endDrag);
  }

  function bindToggleButton(root, toggle) {
    toggle.type = 'button';
    toggle.setAttribute('aria-expanded', String(root.classList.contains('is-open')));
    toggle.setAttribute('aria-label', '苍玄界状态栏');
    toggle.title = '苍玄界状态栏';
    toggle.innerHTML = '<span class="cx-floating-status-glyph">灵</span>';
    toggle.addEventListener('click', ev => {
      ev.preventDefault();
      ev.stopPropagation();
      if (root.dataset.cxDragged === '1') return;
      const isOpen = root.classList.toggle('is-open');
      toggle.setAttribute('aria-expanded', String(isOpen));
      if (isOpen) requestFrameLoad(root);
    });
    return toggle;
  }

  function replaceAndBindToggle(root, toggle) {
    const hostDoc = getHostDocument();
    const nextToggle = hostDoc.createElement('button');
    nextToggle.id = TOGGLE_ID;
    nextToggle.className = toggle?.className || '';
    if (toggle?.style?.cssText) nextToggle.style.cssText = toggle.style.cssText;
    if (toggle?.parentNode) toggle.replaceWith(nextToggle);
    return bindToggleButton(root, nextToggle);
  }

  function bridgeGlobals(win) {
    const bridge = {
      getGlobal: getOuterGlobal,
      getMvu: getMvuObj,
      writeStatusInteraction: writeStatusInteractionToInput,
      instanceId: INSTANCE_ID,
    };
    try {
      getHostWindow().__CX_TH__ = bridge;
      getHostWindow().writeStatusInteraction = writeStatusInteractionToInput;
    } catch (_) {}
    try {
      win.__CX_TH__ = bridge;
      win.writeStatusInteraction = writeStatusInteractionToInput;
    } catch (_) {}
    const names = [
      'Mvu', '_', 'getAllVariables', 'getVariables', 'getCurrentMessageId',
      'eventOn', 'eventEmit', 'tavern_events', 'waitGlobalInitialized',
      'errorCatched', 'toastr', 'getScriptId', 'getChatMessages', 'getLastMessageId',
      'setChatMessages', 'setChatMessage', 'triggerSlash',
      'substitudeMacros', 'SillyTavern', 'name1',
    ];
    for (const name of names) {
      try {
        const value = getOuterGlobal(name);
        if (value !== undefined) win[name] = value;
      } catch (_) {}
    }
    installInputDraftBridge(win);
    try {
      const jq = getOuterGlobal('$');
      if (jq) {
        const scopedJq = new Proxy(function(selector, context) {
          if (typeof selector === 'function') {
            return jq(() => selector.call(win.document, jq));
          }
          return jq(selector, context || win.document);
        }, {
          get(_target, prop) {
            return jq[prop];
          },
          set(_target, prop, value) {
            jq[prop] = value;
            return true;
          },
          has(_target, prop) {
            return prop in jq;
          },
        });
        win.$ = scopedJq;
        win.jQuery = scopedJq;
      }
    } catch (_) {}
  }

  async function loadFrame(iframe) {
    if (!iframe || iframe.dataset[FRAME_BUILD_ATTR] === BUILD_ID) return;
    iframe.dataset[FRAME_BUILD_ATTR] = `${BUILD_ID}-loading`;
    await waitForMvuObj();
    if (!iframe.isConnected) {
      delete iframe.dataset[FRAME_BUILD_ATTR];
      return;
    }
    const statusHtml = decodeBase64Utf8(STATUS_HTML_BASE64);
    const win = iframe.contentWindow;
    const doc = iframe.contentDocument;
    if (!win || !doc) {
      delete iframe.dataset[FRAME_BUILD_ATTR];
      return;
    }
    bridgeGlobals(win);
    doc.open();
    doc.write(statusHtml);
    doc.close();
    iframe.dataset[FRAME_BUILD_ATTR] = BUILD_ID;
    [0, 100, 500, 1500].forEach(delay => setTimeout(() => bridgeGlobals(win), delay));
  }

  function requestFrameLoad(root) {
    const iframe = root?.querySelector?.(`#${FRAME_ID}`);
    if (!iframe || iframe.dataset[FRAME_BUILD_ATTR] === BUILD_ID) return;
    loadFrame(iframe).catch(error => {
      try { delete iframe.dataset[FRAME_BUILD_ATTR]; } catch (_) {}
      console.warn('[苍玄界状态栏] 加载状态栏 iframe 失败', error);
    });
  }

  function ensureFloatingStatus() {
    const hostDoc = getHostDocument();
    const existing = hostDoc.getElementById(ROOT_ID);
    if (existing) {
      const existingToggle = existing.querySelector(`#${TOGGLE_ID}`);
      const existingFrame = existing.querySelector(`#${FRAME_ID}`);
      if (existingToggle && existingFrame) {
        existing.dataset.cxStatusInstance = INSTANCE_ID;
        existing.style.display = '';
        existing.style.visibility = '';
        existing.style.opacity = '';
        ensureStyle();
        const reboundToggle = replaceAndBindToggle(existing, existingToggle);
        installDrag(existing, reboundToggle);
        return existing;
      }
      existing.remove();
    }
    ensureStyle();

    const root = hostDoc.createElement('div');
    root.id = ROOT_ID;
    root.dataset.cxStatusInstance = INSTANCE_ID;

    const panel = hostDoc.createElement('div');
    panel.id = PANEL_ID;

    const iframe = hostDoc.createElement('iframe');
    iframe.id = FRAME_ID;
    iframe.title = '苍玄界状态栏';
    iframe.setAttribute('allowtransparency', 'true');
    panel.appendChild(iframe);

    const toggle = hostDoc.createElement('button');
    toggle.id = TOGGLE_ID;
    bindToggleButton(root, toggle);

    root.appendChild(panel);
    root.appendChild(toggle);
    hostDoc.body.appendChild(root);
    applyInitialPosition(root);
    installDrag(root, toggle);
    return root;
  }

  function cleanupFloatingStatus() {
    const hostDoc = getHostDocument();
    const root = hostDoc.getElementById(ROOT_ID);
    if (root?.dataset.cxStatusInstance === INSTANCE_ID) root.remove();
    const style = hostDoc.getElementById(STYLE_ID);
    if (!hostDoc.getElementById(ROOT_ID) && style) style.remove();
    try {
      if (getHostWindow().__CX_TH__?.instanceId === INSTANCE_ID) delete getHostWindow().__CX_TH__;
    } catch (_) {}
  }

  function safeEnsureFloatingStatus() {
    try {
      return ensureFloatingStatus();
    } catch (error) {
      console.warn('[苍玄界状态栏] 挂载悬浮按钮失败', error);
      return null;
    }
  }

  try {
    const oldWatchdog = getHostWindow().__CX_STATUS_WATCHDOG__;
    if (oldWatchdog) clearInterval(oldWatchdog);
    delete getHostWindow().__CX_STATUS_WATCHDOG__;
  } catch (_) {}

  safeEnsureFloatingStatus();

  const eventOnFn = getOuterGlobal('eventOn');
  const tavernEvents = getOuterGlobal('tavern_events');
  if (typeof eventOnFn === 'function' && tavernEvents) {
    const ensureLater = () => setTimeout(safeEnsureFloatingStatus, 200);
    eventOnFn(tavernEvents.CHAT_CHANGED, ensureLater);
  }

  $(window).on('pagehide', () => {
    try {
      const oldWatchdog = getHostWindow().__CX_STATUS_WATCHDOG__;
      if (oldWatchdog) clearInterval(oldWatchdog);
      delete getHostWindow().__CX_STATUS_WATCHDOG__;
    } catch (_) {}
  });
  try {
    getHostWindow().addEventListener('beforeunload', cleanupFloatingStatus, { once: true });
  } catch (_) {}
});
